_WF_AUTHOR_TOOLS_DENY = [
    "exec", "process", "read", "write", "edit", "file_write", "file_fetch",
    "dir_list", "dir_fetch", "browser", "canvas", "cron", "gateway",
    "message", "subagents", "sessions_list", "sessions_history",
    "sessions_yield", "session_status", "agents_list", "memory_search",
    "memory_get", "wiki_search", "wiki_get", "wiki_lint", "wiki_apply",
    "request_approval", "approval_status", "guest_send",
    "request_purchase", "prospect_update", "prospects_search",
    "agenda_slots", "agenda_book", "kb_search", "workflow_list",
